fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // The number of columns is determined by the length of the index array.
    let n = indices.len();
    // Pre-allocate the result vector with the right capacity.
    let mut result = Vec::with_capacity(n);

    for (col, &row_idx) in indices.iter().enumerate() {
        // Convert the u8 index to usize for indexing into `choices`.
        let r = row_idx as usize;
        // Fetch the chosen element: row `r`, column `col`.
        result.push(choices[r][col]);
    }

    result
}

